-- Object-level: schema and table
GRANT SELECT ON SCHEMA::sales TO [sg-sales-analysts];
DENY SELECT ON OBJECT::sales.Payroll TO [sg-sales-analysts];

-- Column-level: list allowed columns, CreditCard is excluded
GRANT SELECT ON dbo.Customers (CustomerID, FirstName, LastName, Email)
    TO [charlie@contoso.com];

-- Run as charlie: fails with Msg 230 on column CreditCard
SELECT * FROM dbo.Customers;

-- Check effective permissions of the current user
SELECT * FROM sys.fn_my_permissions('dbo.Customers', 'Object');

ALTER TABLE dbo.EmployeeData
    ALTER COLUMN Email ADD MASKED WITH (FUNCTION = 'email()');

ALTER TABLE dbo.EmployeeData
    ALTER COLUMN Phone ADD MASKED WITH (FUNCTION = 'partial(3,"XXX-XXXX",0)');

GRANT UNMASK ON dbo.EmployeeData TO [sg-hr-managers];
REVOKE UNMASK ON dbo.EmployeeData TO [sg-hr-managers];

ALTER TABLE dbo.EmployeeData ALTER COLUMN Email DROP MASKED;
